import { Component, Element, Event, EventEmitter, h, Host } from '@stencil/core';

@Component({
  tag: 'groupui-breadcrumb-dropdown',
  styleUrl: 'breadcrumb-dropdown.scss',
  shadow: true,
})
export class BreadcrumbDropdown {
  @Element() host: HTMLElement;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  render() {
    return (
      <Host>
        <div>
          <slot />
        </div>
      </Host>
    );
  }
}
