import { Component, ComponentInterface, Element, Event, EventEmitter, h, Host, Listen, Prop } from '@stencil/core';
import { Target } from '../../../types';

@Component({
  tag: 'groupui-breadcrumb',
  styleUrl: 'breadcrumb.scss',
  shadow: true,
})
export class Breadcrumb implements ComponentInterface {
  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly inDropdown: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly first: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly last: boolean;

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1
   */
  @Prop({ reflect: true }) readonly href?: string;

  /**
   * where to display the linked URL
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    this.updateHrefAttribute();
    this.groupuiDidLoad.emit();
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'Enter') {
      this.getNativeLink()?.click();
    }
  }

  private updateHrefAttribute() {
    this.href && this.getNativeLink().setAttribute('href', this.href);
  }

  private getNativeLink(): HTMLElement {
    return this.host.shadowRoot.querySelector('a');
  }

  private slotContainsText() {
    return this.host.textContent.trim().length > 0;
  }

  private static verifyTarget(target: Target): string {
    return target.startsWith('_') ? target : `_${target}`;
  }

  render() {
    return (
      <Host>
        <a tabIndex={-1} target={Breadcrumb.verifyTarget(this.target)}>
          <div id="outer">
            <div id="inner">{this.slotContainsText() && <slot />}</div>
          </div>
        </a>
        {!this.last && !this.inDropdown && <groupui-icon name="chevron-right-16" aria-hidden="true"></groupui-icon>}
        <slot name="dropdown" />
      </Host>
    );
  }
}
